\title{Intrinsic Curvature of an Anisotropic\\Hyperbolic-Coefficient Plane}
\author{Aristotle}
\date{July 18, 2026}
\begin{document}
\maketitle

\begin{abstract}
We study the smooth Riemannian metric
\[
g=\cosh(y)^{-2}\,dx^2+\cosh(x)^2\,dy^2
\]
on $\mathbb R^2$. A coordinate calculation yields
\[
K(x,y)=-\cosh^2y+\frac{1-\sinh^2y}{\cosh^2x\cosh^2y}.
\]
We identify this scalar intrinsically. The algebraic curvature tensor determined by $K$ and the metric has the standard alternating, pair-interchange, and Bianchi symmetries, and its sectional quotient equals $K$ for every nondegenerate tangent frame. The key identity expresses the Gram determinant as the metric determinant times squared oriented coordinate area. Finally, $K$ is nonpositive everywhere, vanishes exactly at the origin, and is strictly negative elsewhere. We discuss numerical algorithms, metric area, applications, and the global geometric questions left open.
\end{abstract}

\section{Introduction}
The metric
\[
ds^2=\frac{dx^2}{\cosh^2y}+\cosh^2x\,dy^2
\]
is strongly anisotropic. Horizontal motion becomes inexpensive as $|y|$ grows, whereas vertical motion becomes expensive as $|x|$ grows. Neither coefficient is uniformly comparable to a fixed positive constant on the whole plane, making global questions such as completeness nontrivial.

A coordinate curvature formula becomes geometrically meaningful only after identification with a frame-independent quantity. On a surface, sectional curvature is obtained by evaluating a curvature tensor on two independent tangent vectors and dividing by their squared metric area. We establish this identification directly and classify the sign and zero locus of the curvature.

\section{Metric and tangent area}
Let $M=\mathbb R^2$, $p=(x,y)$, and $u=(u_1,u_2)$, $v=(v_1,v_2)$. Define
\[
g_p(u,v)=E(p)u_1v_1+G(p)u_2v_2,
\qquad E=\cosh(y)^{-2},\quad G=\cosh(x)^2.
\]
Both coefficients are smooth and positive, so $g$ is a smooth positive-definite metric. Its determinant and area element are
\[
\det g_p=E(p)G(p)=\frac{\cosh^2x}{\cosh^2y}>0,
\qquad dA_g=\frac{\cosh x}{\cosh y}\,dx\,dy.
\]

\begin{definition}
The oriented coordinate area and Gram determinant of a tangent pair are
\[
\omega(u,v)=u_1v_2-u_2v_1,
\qquad
\Gamma_p(u,v)=g_p(u,u)g_p(v,v)-g_p(u,v)^2.
\]
The frame is nondegenerate when $\omega(u,v)\ne0$.
\end{definition}

\begin{lemma}[Gram Determinant Identity]
For every point and tangent pair,
\[
\Gamma_p(u,v)=E(p)G(p)\omega(u,v)^2
=\frac{\cosh^2x}{\cosh^2y}(u_1v_2-u_2v_1)^2.
\]
\end{lemma}
\begin{proof}
Insert
\[
g(u,u)=Eu_1^2+Gu_2^2,\quad g(v,v)=Ev_1^2+Gv_2^2,
\quad g(u,v)=Eu_1v_1+Gu_2v_2.
\]
The pure $E^2$ and $G^2$ terms cancel, while the remaining terms equal
$EG(u_1^2v_2^2+u_2^2v_1^2-2u_1u_2v_1v_2)=EG\omega(u,v)^2$.
\end{proof}

\begin{corollary}[Positive frame area]
If $\omega(u,v)\ne0$, then $\Gamma_p(u,v)>0$.
\end{corollary}
\begin{proof}
Both $E(p)G(p)$ and the square of the nonzero number $\omega(u,v)$ are positive.
\end{proof}

\section{Algebraic curvature reconstruction}
Define
\[
K(p)=-\cosh^2y+\frac{1-\sinh^2y}{\cosh^2x\cosh^2y}
\]
and
\[
R_p(u,v,w,z)=K(p)\bigl(g_p(u,w)g_p(v,z)-g_p(u,z)g_p(v,w)\bigr).
\]

\begin{proposition}[Curvature symmetries]
For all tangent vectors $u,v,w,z$,
\begin{align*}
R_p(v,u,w,z)&=-R_p(u,v,w,z),\\
R_p(u,v,z,w)&=-R_p(u,v,w,z),\\
R_p(w,z,u,v)&=R_p(u,v,w,z),\\
R_p(u,v,w,z)+R_p(v,w,u,z)+R_p(w,u,v,z)&=0.
\end{align*}
\end{proposition}
\begin{proof}
The first two identities follow by exchanging the two products in the defining difference. The third follows from symmetry of $g$. For the final identity, expand the cyclic sum; every product of two metric pairings appears once with each sign.
\end{proof}

These identities are respectively alternation in each pair, pair-interchange symmetry, and the algebraic first Bianchi identity. Thus the displayed formula has the standard algebraic behavior of a Riemann curvature tensor.

\section{Intrinsic sectional curvature}
\begin{lemma}[Repeated-frame evaluation]
For every $p,u,v$,
\[
R_p(u,v,u,v)=K(p)\Gamma_p(u,v).
\]
\end{lemma}
\begin{proof}
Substitution gives $K(p)[g(u,u)g(v,v)-g(u,v)g(v,u)]$, and symmetry of the metric identifies the bracket with $\Gamma_p(u,v)$.
\end{proof}

For a nondegenerate frame define
\[
\operatorname{Sec}_p(u,v)=\frac{R_p(u,v,u,v)}{\Gamma_p(u,v)}.
\]

\begin{theorem}[Intrinsic Curvature Identification]
For every point $p$ and every nondegenerate tangent frame $(u,v)$,
\[
\operatorname{Sec}_p(u,v)=K(p).
\]
\end{theorem}
\begin{proof}
The repeated-frame lemma makes the numerator $K(p)\Gamma_p(u,v)$. The Gram determinant is positive for a nondegenerate frame, so it cancels.
\end{proof}

The theorem is unchanged by tilting, rescaling, or reversing the orientation of the frame. In dimension two every nondegenerate pair spans the same tangent plane; equivalently, the metric wedge square is one-dimensional. This explains why one scalar determines the full algebraic curvature tensor. A parallel pair is properly excluded because it encloses no area and gives a zero denominator.

\section{Sign and zero locus}
\begin{theorem}[Global nonpositivity]
For all $(x,y)\in\mathbb R^2$, $K(x,y)\le0$.
\end{theorem}
\begin{proof}
Set $a=\sinh^2x\ge0$ and $b=\sinh^2y\ge0$. Since $\cosh^2t=1+\sinh^2t$,
\[
K=-(1+b)+\frac{1-b}{(1+a)(1+b)}.
\]
Multiplying by the positive number $(1+a)(1+b)$ and changing sign produces
\[
(1+a)(1+b)^2-(1-b)=a+3b+2ab+b^2+ab^2\ge0.
\]
Therefore $K\le0$.
\end{proof}

\begin{theorem}[Unique flat point]
For all $(x,y)$,
\[
K(x,y)=0\quad\Longleftrightarrow\quad(x,y)=(0,0).
\]
\end{theorem}
\begin{proof}
Equality in the preceding sum of nonnegative terms forces $a=b=0$. Since $\sinh t=0$ exactly when $t=0$, this forces $x=y=0$. Conversely, substitution gives $K(0,0)=-1+1=0$.
\end{proof}

\begin{corollary}[Strict sectional negativity]
If $p\ne(0,0)$ and $(u,v)$ is nondegenerate, then
$\operatorname{Sec}_p(u,v)<0$.
\end{corollary}
\begin{proof}
The sectional quotient equals $K(p)$, which is nonpositive and cannot vanish away from the origin.
\end{proof}

Thus the flat locus is an isolated point, not a boundary between positive and negative regions. Along the horizontal axis,
\[
K(x,0)=-1+\cosh(x)^{-2}=-\tanh^2x,
\]
which tends to $-1$. Along the vertical axis, the term $-\cosh^2y$ drives the curvature rapidly to $-\infty$.

\section{Algorithms and numerical exploration}
\subsection{Pointwise evaluation}
At a point $(x,y)$ compute $c_x=\cosh x$, $c_y=\cosh y$, and $s_y=\sinh y$, then return
\[
-c_y^2+\frac{1-s_y^2}{c_x^2c_y^2}.
\]
This has $O(1)$ arithmetic complexity per point and $O(N)$ complexity for $N$ samples. Very large arguments require scaled or arbitrary-precision hyperbolic functions to avoid overflow.

\subsection{Frame-invariance diagnostic}
Given $p,u,v$, compute $\omega=u_1v_2-u_2v_1$ and reject frames with $|\omega|$ below a tolerance. Compute the direct Gram determinant, compare it with $(\det g_p)\omega^2$, and evaluate $R(u,v,u,v)/\Gamma$. The quotient agrees with $K(p)$ up to floating-point error. Near parallelism the ratio of two small quantities is ill-conditioned, so direct evaluation of $K$ is preferred for production calculations.

\subsection{Grid visualization}
For an $N_x$ by $N_y$ rectangular grid, evaluate $K$ at every point. Time and retained-grid storage are $O(N_xN_y)$; streaming extrema need only $O(1)$ auxiliary storage. If the origin is sampled, the maximum is $0$ there. Heat maps display even symmetry in both coordinates and much steeper vertical than horizontal decay.

\section{Area and geometric applications}
For a measurable region $\Omega$,
\[
\operatorname{Area}_g(\Omega)=\iint_\Omega\frac{\cosh x}{\cosh y}\,dx\,dy.
\]
For a coordinate rectangle $[a,b]\times[c,d]$, this separates as
\[
\left(\int_a^b\cosh x\,dx\right)
\left(\int_c^d\frac{dy}{\cosh y}\right).
\]
A geodesic triangle requires specified vertices and specified geodesic segments. Curvature signs alone do not determine its area.

The intrinsic identification also supplies the scalar entering normal Jacobi equations, independently of the chosen tangent frame. Strict negativity suggests divergence of nearby geodesics, but quantitative statements require curvature bounds along actual geodesics.

\section{Scope and future work}
The established statements are pointwise and algebraic. A connection-level treatment should derive the Levi--Civita connection and compare its curvature operator directly with $R$. Global completeness also remains open: horizontal compression and vertical expansion may combine with conserved energy to prevent finite-time escape, but no uniform Euclidean comparison is available.

Further questions include whether a nonconstant geodesic can pass through the isolated flat point more than once, whether the exponential map at the origin is a global diffeomorphism after completeness is established, and whether geodesics avoiding a neighborhood of the origin admit quantitative Jacobi-field growth estimates. Finally, in dimension two one expects a rigidity theorem asserting that compatibility with the metric and one sectional value at each point uniquely determines the algebraic curvature tensor.

\section{Conclusion}
The anisotropic split metric has an exact intrinsic curvature description. Its Gram determinant equals metric determinant times squared coordinate area; its reconstructed four-tensor has all algebraic curvature symmetries; and every nondegenerate sectional quotient equals the scalar $K$. This curvature is nonpositive everywhere, zero only at the origin, and strictly negative elsewhere. The result supplies the invariant local foundation needed for future analysis of geodesics, completeness, exponential maps, and global rigidity.

\end{document}

